source:
OnDemandTiles(BasemapFixtures.store(dir), () => c, OnDemandTiles.Source.Planet(() => "fake://planet"), () => p, () => clock.get.toLong, ms => {
  slept.addAndGet(ms.toInt)
  ()
})

